/**
 * Read-only Convex client for the brain MCP tools.
 *
 * The MCP `convex` server needs an interactive login (unavailable to an
 * autonomous run), so the brain read tools talk to Convex over HTTP exactly like
 * `server/scripts/convexParity.ts` and `server/services/convexMirror.ts`: a lazy
 * `ConvexHttpClient` built from `VITE_CONVEX_URL`/`CONVEX_URL`. Reads are
 * unguarded in P0–P4 (the dashboard subscribes anonymously), so the read tools
 * need only the URL — no write secret.
 *
 * The query embedding for `memory_search` is computed on THIS (Node) side with
 * the pluggable embedder (`defaultEmbedder`, mock by default), because the
 * Convex deployment owns no API key — the retrieve action takes the vector.
 */
import { ConvexHttpClient } from 'convex/browser';

import { api } from '../../convex/_generated/api';
import { defaultEmbedder, type Embedder } from '../services/embeddings';

function convexUrl(): string | undefined {
  return process.env.CONVEX_URL ?? process.env.VITE_CONVEX_URL;
}

/** Thrown when a brain tool runs without a configured Convex deployment. */
export class ConvexUnconfiguredError extends Error {
  constructor() {
    super(
      'Convex is not configured: set VITE_CONVEX_URL (or CONVEX_URL) in .env.local. ' +
        'Brain read tools require a deployment URL.',
    );
    this.name = 'ConvexUnconfiguredError';
  }
}

let cached: ConvexHttpClient | null = null;

/** Lazily construct (and cache) the read client. Throws if unconfigured. */
export function getBrainClient(): ConvexHttpClient {
  const url = convexUrl();
  if (!url) throw new ConvexUnconfiguredError();
