// OKLCH -> sRGB hex (standard Ottosson matrices), color-mix in oklch approximated by linear interpolation of L,C,H.
const toHex = (L,C,H) => {
  const h = H*Math.PI/180, a = C*Math.cos(h), b = C*Math.sin(h);
  const l_ = L + 0.3963377774*a + 0.2158037573*b, m_ = L - 0.1055613458*a - 0.0638541728*b, s_ = L - 0.0894841775*a - 1.2914855480*b;
  const l=l_**3, m=m_**3, s=s_**3;
  let r= 4.0767416621*l - 3.3077115913*m + 0.2309699292*s, g=-1.2684380046*l + 2.6097574011*m - 0.3413193965*s, bl=-0.0041960863*l - 0.7034186147*m + 1.7076147010*s;
  const enc = x => { x = Math.min(1, Math.max(0, x)); x = x <= 0.0031308 ? 12.92*x : 1.055*x**(1/2.4) - 0.055; return Math.round(x*255).toString(16).padStart(2,'0'); };
  return '#' + enc(r) + enc(g) + enc(bl);
};
const mix = (c1, p, c2) => c1.map((v,i) => v*p + c2[i]*(1-p));
const T = {
